typedef unsigned long long uint64;

class stringx
{
  char *chars;
  void *my_buf;
public:
  stringx &operator=(const stringx &cp);
};

class pstring
{
  uint64 pchunk[4];
  void pack_string(const char *the_string);
public:
  pstring(const char *target_string)
  {
    pack_string(target_string);
  }

  bool operator == (const pstring &check_me) const
  {
    for (unsigned i=0; i<4; ++i)
    {
      if (pchunk[i] != check_me.pchunk[i])
        return false;
    }
    return true;
  }
};

class game_info
{
protected:
  int difficulty;
  stringx hero_name_0;
  stringx hero_name_1;
public:
  bool get_str(const pstring &att, stringx &val) const;
};

bool game_info::get_str(const pstring &att, stringx &val) const
{
#define MAC(type, var, def, str)  { static pstring pstring_get(##str##); if(att == pstring_get) { val = ##var##; return(true); } }
#define GAME_INFO_STRS
MAC(stringx, hero_name_0, 0, "HERO_NAME_0");
MAC(stringx, hero_name_1, 0, "HERO_NAME_1");
#undef GAME_INFO_STRS
#undef MAC

	return(false);
}
